"""Small account registry with optional public signup. Workspace IDs are generated by the server."""
import secrets
import sqlite3
import time
import re

from app.api.errors import ApiError

TERMS_VERSION = "2026-10-14"


class Accounts:
    def __init__(self, cfg, bootstrap):
        cfg.data_dir.mkdir(parents=True, exist_ok=True)
        self.limit = cfg.max_accounts
        self.public_signup = cfg.public_signup
        self.con = sqlite3.connect(cfg.data_dir / "accounts.db", check_same_thread=False)
        self.con.row_factory = sqlite3.Row
        self.con.executescript("""
            PRAGMA journal_mode=WAL;
            PRAGMA synchronous=FULL;
            CREATE TABLE IF NOT EXISTS accounts (
                id TEXT PRIMARY KEY, username TEXT UNIQUE COLLATE NOCASE NOT NULL,
                role TEXT NOT NULL, salt TEXT NOT NULL, password_hash TEXT NOT NULL,
                collector_key_hash TEXT UNIQUE, disabled INTEGER NOT NULL DEFAULT 0,
                created_at REAL NOT NULL, terms_version TEXT, accepted_at REAL);
            CREATE TABLE IF NOT EXISTS invites (
                token_hash TEXT PRIMARY KEY, created_at REAL NOT NULL, expires_at REAL NOT NULL,
                used_by TEXT, revoked INTEGER NOT NULL DEFAULT 0);
            CREATE TABLE IF NOT EXISTS acceptances (
                account_id TEXT NOT NULL, version TEXT NOT NULL, accepted_at REAL NOT NULL,
                PRIMARY KEY(account_id, version));
        """)
        with self.con:
            # Import the original owner once. Existing logs keep their original data directory.
            self.con.execute("""INSERT OR IGNORE INTO accounts
                (id,username,role,salt,password_hash,collector_key_hash,created_at)
                VALUES ('owner',?,'admin',?,?,?,?)""", (bootstrap["username"], bootstrap["salt"],
                    bootstrap["password_hash"], bootstrap["collector_key_hash"], time.time()))

    def by_id(self, account_id):
        return self.con.execute("SELECT * FROM accounts WHERE id=? AND disabled=0", (account_id,)).fetchone()

    def by_name(self, username):
        return self.con.execute("SELECT * FROM accounts WHERE username=? COLLATE NOCASE AND disabled=0", (username,)).fetchone()

    def by_key(self, key_hash):
        return self.con.execute("SELECT * FROM accounts WHERE collector_key_hash=? AND disabled=0", (key_hash,)).fetchone()

    def list(self):
        return [dict(r) for r in self.con.execute(
            "SELECT id,username,role,disabled,created_at,terms_version,accepted_at FROM accounts ORDER BY created_at")]

    def invite(self):
        from app.auth import digest
        now = time.time()
        accounts = self.con.execute("SELECT COUNT(*) FROM accounts").fetchone()[0]
        pending = self.con.execute("SELECT COUNT(*) FROM invites WHERE used_by IS NULL AND revoked=0 AND expires_at>?", (now,)).fetchone()[0]
        if accounts + pending >= self.limit:
            raise ApiError(409, "account_limit", f"This pilot allows {self.limit} accounts, including pending invitations.")
        token = secrets.token_urlsafe(32)
        with self.con:
            self.con.execute("INSERT INTO invites(token_hash,created_at,expires_at) VALUES (?,?,?)", (digest(token), now, now + 86400))
        return {"token": token, "expires_at": now + 86400, "id": digest(token)}

    def register(self, invite, username, password, version):
        from app.auth import digest, make_credentials
        if version != TERMS_VERSION:
            raise ApiError(422, "terms_required", "Accept the current Terms and Privacy Notice to create an account.")
        username = username.strip()
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{2,63}", username):
            raise ApiError(422, "validation_error", "Username must be 3–64 letters, numbers, dots, underscores or hyphens.")
        if not 12 <= len(password) <= 1024:
            raise ApiError(422, "validation_error", "Use a password of at least 12 characters.")
        now = time.time()
        if invite or not self.public_signup:
            inv = self.con.execute("SELECT * FROM invites WHERE token_hash=?", (digest(invite),)).fetchone()
            if not inv or inv["used_by"] or inv["revoked"] or inv["expires_at"] <= now:
                raise ApiError(400, "invalid_invite", "This invitation is invalid, expired or already used. Ask the owner for a new one.")
        if self.con.execute("SELECT COUNT(*) FROM accounts").fetchone()[0] >= self.limit:
            raise ApiError(409, "account_limit", "This pilot has reached its account limit.")
        if self.con.execute("SELECT 1 FROM accounts WHERE username=? COLLATE NOCASE", (username,)).fetchone():
            raise ApiError(409, "username_taken", "That username is already in use.")
        credentials = make_credentials(username, password, secrets.token_urlsafe(32))
        account_id = secrets.token_hex(16)
        try:
            with self.con:
                self.con.execute("""INSERT INTO accounts
                    (id,username,role,salt,password_hash,created_at,terms_version,accepted_at)
                    VALUES (?,?,'member',?,?,?,?,?)""", (account_id, username, credentials["salt"],
                        credentials["password_hash"], now, version, now))
                if invite:
                    self.con.execute("UPDATE invites SET used_by=? WHERE token_hash=?", (account_id, digest(invite)))
                self.con.execute("INSERT INTO acceptances VALUES (?,?,?)", (account_id, version, now))
        except sqlite3.IntegrityError:
            raise ApiError(409, "username_taken", "That username is already in use.") from None
        return account_id

    def accept(self, account_id, version):
        if version != TERMS_VERSION:
            raise ApiError(422, "terms_required", "Accept the current Terms and Privacy Notice.")
        now = time.time()
        with self.con:
            self.con.execute("UPDATE accounts SET terms_version=?,accepted_at=? WHERE id=?", (version, now, account_id))
            self.con.execute("INSERT OR IGNORE INTO acceptances VALUES (?,?,?)", (account_id, version, now))

    def rotate_key(self, account_id):
        from app.auth import digest
        key = secrets.token_urlsafe(32)
        with self.con:
            self.con.execute("UPDATE accounts SET collector_key_hash=? WHERE id=?", (digest(key), account_id))
        return key

    def disable(self, account_id):
        if account_id == "owner":
            raise ApiError(409, "owner_required", "The owner account cannot be disabled.")
        with self.con:
            row = self.con.execute("UPDATE accounts SET disabled=1,collector_key_hash=NULL WHERE id=?", (account_id,))
        if not row.rowcount:
            raise ApiError(404, "not_found", "Account not found")

    def close(self):
        self.con.close()
